import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation to efficiently test membership of items in a set
    with a specified false positive rate. It uses a bit array and multiple hash functions
    to compute the indices for storage in the bit array.

    Optimal size of the bit array and number of hash functions are calculated based on
    the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal sizes
        self.size = self._optimal_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_hash_count(self.size, expected_items)

        # Initialize bit array
        self.bit_array = [0] * self.size

    def _optimal_size(self, n: int, p: float) -> int:
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_count(self, m: int, n: int) -> int:
        return max(1, round((m / n) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        # Create a unique hash for the item and the seed
        hasher = hashlib.md5()
        hasher.update(f"{seed}{item}".encode('utf-8'))
        return int(hasher.hexdigest(), 16) % self.size

    def add(self, item: str) -> None:
        for seed in range(self.hash_count):
            idx = self._hash(item, seed)
            self.bit_array[idx] = 1

    def contains(self, item: str) -> bool:
        for seed in range(self.hash_count):
            idx = self._hash(item, seed)
            if self.bit_array[idx] == 0:
                return False
        return True

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses an efficient bit representation and multiple
    hash functions to optimize membership testing. The filter computes the optimal size
    of the bit array and number of hash functions based on the expected number of items
    and desired false positive rate, effectively balancing memory usage and accuracy.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0 or not (0 < false_positive_rate < 1):
            raise ValueError("Expected items must be > 0 and false positive rate must be in (0, 1)")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._optimal_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_hash_count(self.size, expected_items)

        self.bit_array = 0  # Using an integer for bit array representation

    def _optimal_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, round((m / n) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash value for the item concatenated with its seed."""
        hasher = hashlib.sha256()
        hasher.update(f"{item}:{seed}".encode('utf-8'))
        return int(hasher.hexdigest(), 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for seed in range(self.hash_count):
            idx = self._hash(item, seed)
            self.bit_array |= (1 << idx)  # Set the bit at the computed index

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        for seed in range(self.hash_count):
            idx = self._hash(item, seed)
            if not (self.bit_array & (1 << idx)):  # Check if the bit is set
                return False
        return True
